def transform(grid):
    out = [row[:] for row in grid]
    # Mark the single-cell interruption in a colored rectangular boundary.
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != grid[0][0]]
    if not cells:
        return out
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    candidates = []
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and grid[r][c] == grid[0][0]:
                # Only fill a gap bracketed by same-colored pixels in a straight line.
                if r in (r0, r1) and c0 < c < c1 and grid[r][c-1] == grid[r][c+1] and grid[r][c-1] != grid[0][0]:
                    candidates.append((r,c))
                if c in (c0, c1) and r0 < r < r1 and grid[r-1][c] == grid[r+1][c] and grid[r-1][c] != grid[0][0]:
                    candidates.append((r,c))
    if candidates:
        # Color the interruption as in the demonstration.
        r,c = candidates[0]
        out[r][c] = 2
    return out
